Item", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "单位不统一"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "基础利润公式是所有利润题的基础。记住利润率的分母是成本。"}]}]}]}$$ AS jsonb), NULL, '数量关系-经济利润问题-基础利润的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "经济利润问题", "基础利润"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_profit_basic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
